const VENTAS_REALES = VENTAS_SEED_DATA.ventas;

// Aplica la semilla una sola vez. Al hacerlo:
//  1) escribe las ventas en mattika.ventas.v1.lumina (fusiona con las del usuario),
//  2) resetea el inventario del alcance a Disponible y aplica los estados reales
//     (Vendido / Separado) con el precio de lista real de cada lote,
//  3) escribe las reservas (venta | separacion) que alimentan Clientes y Pagos.
function seedVentasReales() {
  try {
    const FLAG = 'mattika.ventas-seed.v5';
    if (localStorage.getItem(FLAG)) return;
    const empresaId = 'lumina';
    const scope = VENTAS_SEED_DATA.scope; // lumina.napoles.e1

    // 1) VENTAS — fusiona conservando cualquier venta creada por el usuario.
    // Asigna una cartera realista al asesor demo (Ana Salinas · u-lum-2) para
    // que su "Vista de asesor" tenga datos: sus 2 contratos por firmar + 8 firmados.
    const MI_ASESOR = 'u-lum-2';
    let _asig = 0;
    const seedList = VENTAS_REALES.map(v => {
      if (v.meta && v.meta.asesorId) return v;
      const esPorFirmar = v.status === 'por-firmar';
      if (esPorFirmar || _asig < 8) {
        if (!esPorFirmar) _asig++;
        return { ...v, meta: { ...(v.meta || {}), asesorId: MI_ASESOR, asesorNombre: 'Ana Salinas', equipo: 'E. Interno' } };
      }
      return v;
    });
    const vkey = 'mattika.ventas.v1.' + empresaId;
    let existing = [];
    try { existing = JSON.parse(localStorage.getItem(vkey) || '[]'); } catch (e) {}
    const seedIds = new Set(seedList.map(v => v.id));
    const merged = [...seedList, ...existing.filter(v => !seedIds.has(v.id))];
    localStorage.setItem(vkey, JSON.stringify(merged));

    // 2) LOTES — resetea a Disponible y aplica estados/precios reales.
    const norm = (s) => String(s == null ? '' : s).replace(/[^a-z0-9]/gi, '').toUpperCase();
    const lkey = 'mattika.lotes-admin.v1.' + scope;
    let lotes = [];
    try { lotes = JSON.parse(localStorage.getItem(lkey) || '[]'); } catch (e) {}
    // Si el inventario base no existe todavía (p. ej. store recién vaciado y aún
    // no se abrió la pantalla de Lotes), se genera desde el inventario base de
    // demostración para no quedar con un plano incompleto.
    if (lotes.length < 100 && Array.isArray(window.LOTES_INICIAL) && window.LOTES_INICIAL.length) {
      try { lotes = JSON.parse(JSON.stringify(window.LOTES_INICIAL)); } catch (e) {}
    }
    const byCode = new Map();
    lotes.forEach(l => { l.estado = 'Disponible'; byCode.set(norm(l.codigo || l.id), l); });
    VENTAS_SEED_DATA.lotes.forEach(ls => {
      const l = byCode.get(norm(ls.loteId));
      if (l) { l.estado = ls.estado; if (ls.precio) l.precio = ls.precio; }
      else {
        // Lote real que no existía en el inventario demo: se crea.
        const numero = parseInt(String(ls.loteId).replace(/[^0-9]/g, ''), 10) || 0;
        const nuevo = {
          id: ls.loteId, codigo: ls.loteId, manzana: ls.manzana, numero,
          etapa: '1RA ETAPA', tipologia: 'Lote Residencial',
          m2: 145, frente: 8, fondo: 18, lder: 18, lizq: 18,
          precio: ls.precio || 0, estado: ls.estado,
        };
        lotes.push(nuevo);
        byCode.set(norm(ls.loteId), nuevo);
      }
    });
    localStorage.setItem(lkey, JSON.stringify(lotes));

    // 3) RESERVAS — fuente de verdad para Plano, Clientes y Pagos.
    const rkey = 'mattika.reservas.v1.' + scope;
    let rmap = {};
    try { rmap = JSON.parse(localStorage.getItem(rkey) || '{}'); } catch (e) {}
    VENTAS_SEED_DATA.lotes.forEach(ls => {
      rmap[ls.loteId] = { ...(rmap[ls.loteId] || {}), ...ls.reserva };
    });
    localStorage.setItem(rkey, JSON.stringify(rmap));

    localStorage.setItem(FLAG, '1');
    if (window.console) console.log('[MATTIKA] Semilla de ventas reales aplicada:', VENTAS_REALES.length, 'operaciones');
  } catch (e) { if (window.console) console.warn('[MATTIKA] seedVentasReales falló', e); }
}

Object.assign(window, { VENTAS_REALES, seedVentasReales });
// Ejecuta al cargar (idempotente). El data-store ya está disponible.
try { seedVentasReales(); } catch (e) {}
